package com.thang.user.service.user;
import com.thang.user.repository.*;import com.thang.user.model.entity.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.time.*;
@Service @RequiredArgsConstructor
public class AccountProfileService {
 private final IUserRepository users;private final PasswordEncoder passwords;private final SessionService sessions;private final PasswordRecoveryRepository recoveries;
 public record Profile(String firstName,String lastName,String email,String phone,String address,LocalDate birthday){}
 public record ChangePassword(String currentPassword,String password,String confirmPassword){}
 @Transactional(readOnly=true) public Profile profile(String userId){return view(users.findById(userId).orElseThrow(()->bad("Không tìm thấy tài khoản")));}
 @Transactional public Profile save(String userId,Profile input){if(input==null||input.firstName()==null||input.lastName()==null||input.firstName().isBlank()||input.lastName().isBlank()||input.firstName().length()>100||input.lastName().length()>100||input.phone()!=null&&input.phone().length()>30||input.address()!=null&&input.address().length()>255||input.birthday()!=null&&(input.birthday().isAfter(LocalDate.now())||input.birthday().getYear()<1900))throw bad("Thông tin hồ sơ không hợp lệ");var user=users.lockById(userId).orElseThrow(()->bad("Không tìm thấy tài khoản"));user.setFirstName(input.firstName().trim());user.setLastName(input.lastName().trim());user.setPhoneNumber(input.phone());user.setAddress(input.address());user.setDateOfBirth(input.birthday()==null?null:input.birthday().atStartOfDay());user.setDateModified(LocalDateTime.now());return view(user);}
 @Transactional public void changePassword(String userId,ChangePassword input){var user=users.lockById(userId).orElseThrow(()->bad("Không tìm thấy tài khoản"));if(input==null||input.currentPassword()==null||input.currentPassword().length()>100||user.getPassword()==null||!passwords.matches(input.currentPassword(),user.getPassword()))throw bad("Mật khẩu hiện tại không đúng");if(!PasswordPolicy.valid(input.password())||!input.password().equals(input.confirmPassword()))throw bad("Mật khẩu mới không hợp lệ hoặc xác nhận chưa khớp");user.setPassword(passwords.encode(input.password()));user.setPasswordSetupHash(null);user.setPasswordSetupExpiresAt(null);user.setDateModified(LocalDateTime.now());recoveries.invalidate(userId,System.currentTimeMillis());sessions.removeSession(userId);}
 private Profile view(User user){return new Profile(user.getFirstName(),user.getLastName(),user.getEmail(),user.getPhoneNumber(),user.getAddress(),user.getDateOfBirth()==null?null:user.getDateOfBirth().toLocalDate());}
 private static ResponseStatusException bad(String text){return new ResponseStatusException(HttpStatus.BAD_REQUEST,text);}
}
